package uz.orbitx.arport.engine.registry

import android.content.Context
import org.json.JSONObject
import uz.orbitx.arport.engine.web.WebAppSurface
import uz.orbitx.arport.engine.window.ContentSurface
import uz.orbitx.arport.engine.window.SpatialWindow
import uz.orbitx.arport.engine.window.WindowAspect
import uz.orbitx.arport.engine.window.WindowManager3D
import java.io.BufferedReader
import java.io.InputStreamReader

/**
 * Central registry managing all installed AR Port applications and plugins.
 * Reads app manifests generated by tools/generate_registry.dart.
 */
class AppRegistry(private val context: Context? = null) {

    private val appsMap = mutableMapOf<String, AppManifest>()
    val activeWebSurfaces = mutableMapOf<String, WebAppSurface>()
    val activeNativeApps = mutableMapOf<String, ARApp>()

    val allApps: List<AppManifest>
        get() = appsMap.values.sortedBy { it.order }

    init {
        loadRegistry()
    }

    private fun loadRegistry() {
        var loaded = false
        if (context != null) {
            try {
                context.assets.open("registry/app_registry.json").use { inputStream ->
                    val reader = BufferedReader(InputStreamReader(inputStream))
                    val jsonStr = reader.readText()
                    parseRegistryJson(jsonStr)
                    loaded = true
                }
            } catch (_: Exception) {
                // Fallback to built-in defaults
            }
        }

        if (!loaded || appsMap.isEmpty()) {
            loadDefaultApps()
        }
    }

    fun parseRegistryJson(jsonString: String) {
        val root = JSONObject(jsonString)
        val arr = root.optJSONArray("apps") ?: return
        appsMap.clear()
        for (i in 0 until arr.length()) {
            val appObj = arr.getJSONObject(i)
            val manifest = AppManifest.fromJson(appObj)
            appsMap[manifest.id] = manifest
        }
    }

