            AppManifest("clock", mapOf("uz" to "Soat", "en" to "Clock"), "⏱️", "1.0.0", "native", "tools", "uz.orbitx.arport.engine.apps.ClockApp", "16:9", 0.85f, 0.478f, false, order = 8),
