    fun getApp(id: String): AppManifest? = appsMap[id]

    fun getAppsByCategory(category: String): List<AppManifest> {
        return allApps.filter { it.category.equals(category, ignoreCase = true) }
    }

    fun searchApps(query: String): List<AppManifest> {
        if (query.isBlank()) return allApps
        val q = query.trim().lowercase()
        return allApps.filter {
            it.id.contains(q) ||
            it.name.values.any { n -> n.lowercase().contains(q) } ||
            it.category.lowercase().contains(q)
        }
    }

    /**
     * Launches an app by creating a new SpatialWindow in WindowManager3D.
     */
    fun launchApp(appId: String, windowManager: WindowManager3D): SpatialWindow? {
        val manifest = getApp(appId) ?: return null

        // If app doesn't support multiple windows, check if already open
        if (!manifest.multiWindow) {
            val existing = windowManager.activeWindows.find { it.appId == appId }
            if (existing != null) {
                windowManager.setFocus(existing.id)
                return existing
            }
        }

        val aspect = when (manifest.defaultAspect) {
            "9:16" -> WindowAspect.LOCKED_9_16
            "free" -> WindowAspect.FREE
            else -> WindowAspect.LOCKED_16_9
        }

        val window = windowManager.createWindow(
            appId = manifest.id,
            title = manifest.getLocalizedName("uz"),
            width = manifest.defaultWidth,
            height = manifest.defaultHeight,
            aspect = aspect
        )

        val isPortrait = (aspect == WindowAspect.LOCKED_9_16)
        val surfW = if (isPortrait) 720 else 1280
        val surfH = if (isPortrait) 1280 else 720

        // If Web App or Game and Context available, instantiate real offscreen WebAppSurface
        if (context != null && (manifest.type == "web" || manifest.type == "game2d" || manifest.type == "game")) {
            try {
                val showNav = (manifest.id == "google")
                val webSurface = WebAppSurface(
                    context = context,
                    manifest = manifest,
                    surfaceWidth = surfW,
                    surfaceHeight = surfH,
                    showNavigationBar = showNav
                )
                webSurface.onOpenExternalUrl = { externalUrl ->
                    openInBrowser(externalUrl, windowManager)
                }
                activeWebSurfaces[window.id] = webSurface
                window.contentSurface = webSurface.contentSurface
                return window
            } catch (_: Exception) {
                // Safe fallback to placeholder if headless/mocked
            }
        }

        // If Native App and Context available, instantiate real ARApp surface
        if (context != null && manifest.type == "native") {
            try {
                val nativeApp: ARApp? = when (manifest.id) {
                    "camera" -> uz.orbitx.arport.engine.apps.CameraApp(manifest)
                    "notes" -> uz.orbitx.arport.engine.apps.NotesApp(manifest)
                    "clock" -> uz.orbitx.arport.engine.apps.ClockApp(manifest)
                    "calendar" -> uz.orbitx.arport.engine.apps.CalendarApp(manifest)
                    "settings" -> uz.orbitx.arport.engine.apps.SettingsApp(manifest)
                    else -> null
                }
                if (nativeApp != null) {
                    val surf = nativeApp.createSurface(context, surfW, surfH)
                    activeNativeApps[window.id] = nativeApp
                    window.contentSurface = surf
                    return window
                }
            } catch (_: Exception) {
                // Safe fallback to placeholder if headless/mocked
            }
        }

        val surface = ContentSurface(surfW, surfH)
        window.contentSurface = surface

        renderAppPlaceholderContent(window, manifest)
        return window
    }

    /**
     * Opens an external link inside AR Port's internal Google Browser window.
     */
    fun openInBrowser(url: String, windowManager: WindowManager3D): SpatialWindow? {
        val browserWin = windowManager.activeWindows.find { it.appId == "google" }
        if (browserWin != null) {
            windowManager.setFocus(browserWin.id)
            activeWebSurfaces[browserWin.id]?.loadUrl(url)
            return browserWin
        }
        val newWin = launchApp("google", windowManager)
        newWin?.let {
            activeWebSurfaces[it.id]?.loadUrl(url)
        }
        return newWin
    }

    private fun renderAppPlaceholderContent(window: SpatialWindow, manifest: AppManifest) {
        window.contentSurface?.draw { canvas ->
            canvas.drawColor(android.graphics.Color.parseColor("#E61C1D24"))
            val paint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {
                color = android.graphics.Color.WHITE
                textSize = 54f
                isFakeBoldText = true
            }
            canvas.drawText("${manifest.icon} ${manifest.getLocalizedName("uz")}", 60f, 110f, paint)

            paint.textSize = 28f
            paint.isFakeBoldText = false
            paint.color = android.graphics.Color.parseColor("#8E8E93")
            canvas.drawText("Turi: ${manifest.type.uppercase()} • Kategoriya: ${manifest.category.uppercase()}", 60f, 170f, paint)

            val boxPaint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {
                color = android.graphics.Color.parseColor("#330A84FF")
            }
            canvas.drawRoundRect(android.graphics.RectF(60f, 220f, 660f, 440f), 24f, 24f, boxPaint)

            paint.color = android.graphics.Color.parseColor("#64D2FF")
            paint.textSize = 32f
            paint.isFakeBoldText = true
            canvas.drawText("Ilova faol holatda", 90f, 310f, paint)

            paint.color = android.graphics.Color.WHITE
            paint.textSize = 24f
            paint.isFakeBoldText = false
            canvas.drawText("Kirish nuqtasi: ${manifest.entry}", 90f, 370f, paint)
        }
    }

    /**
     * Releases all active web surfaces and native app surfaces.
     */
    fun release() {
        for ((_, surface) in activeWebSurfaces) {
            surface.release()
        }
        activeWebSurfaces.clear()

        for ((_, app) in activeNativeApps) {
            app.onDestroy()
        }
        activeNativeApps.clear()
    }
}

